typedef struct {
    char *window;
    size_t window_size;
    char *pattern;
    size_t pattern_length;
    size_t start_position;
} HexEditorState;

int find_pattern(HexEditorState *state) {
    // Check for empty pattern
    if (state->pattern_length == 0) {
        return -5; // E1: Empty pattern
    }

    // Check for pattern length exceeding maximum allowed
    if (state->pattern_length > 32) {
        return -5; // E2: Pattern length exceeds maximum allowed
    }

    // Check for invalid start position
    if (state->start_position > state->window_size) {
        return -5; // E3: Start position is out of bounds
    }

    // Perform binary search to find the pattern
    for (size_t i = state->start_position; i <= state->window_size - state->pattern_length; ++i) {
        if (memcmp(state->window + i, state->pattern, state->pattern_length) == 0) {
            return i; // Found the pattern, return its starting index
        }
    }

    return -1; // Pattern not found
}
